package com.rpb.reservation.workforce.attendance.daily;
import java.time.*;import java.util.*;
public final class AttendanceDailyDtos {
 private AttendanceDailyDtos(){}
 public record EffectiveDay(UUID sourceId,UUID storeId,LocalDate workDate,String mode,String state,String sourceType,String sourceFingerprint,long version,Long actualSeconds,Long workSeconds,long paidLeaveSeconds,long unpaidLeaveSeconds,long extraSeconds,Map<String,Object> snapshot,List<String> issues,Long overtimeSeconds,String overtimeState){public EffectiveDay(UUID sourceId,UUID storeId,LocalDate workDate,String mode,String state,String sourceType,String sourceFingerprint,long version,Long actualSeconds,Long workSeconds,long paidLeaveSeconds,long unpaidLeaveSeconds,long extraSeconds,Map<String,Object> snapshot,List<String> issues){this(sourceId,storeId,workDate,mode,state,sourceType,sourceFingerprint,version,actualSeconds,workSeconds,paidLeaveSeconds,unpaidLeaveSeconds,extraSeconds,snapshot,issues,null,"unavailable");}}
 public record DayReviewWrite(UUID employeeId,UUID companyId,LocalDate workDate,Long expectedVersion,String sourceFingerprint,String note){}
 public record RefreshWrite(YearMonth month,List<UUID> employeeIds){}
 public record MonthTotals(Long workSeconds,long paidLeaveSeconds,long unpaidLeaveSeconds,long absenceSeconds,long extraWorkSeconds,long pendingCount,Long overtimeSeconds,Long pendingOvertimeSeconds){public MonthTotals(Long workSeconds,long paidLeaveSeconds,long unpaidLeaveSeconds,long absenceSeconds,long extraWorkSeconds,long pendingCount){this(workSeconds,paidLeaveSeconds,unpaidLeaveSeconds,absenceSeconds,extraWorkSeconds,pendingCount,null,null);}}
 public record EmployeeMonth(UUID employeeId,String employeeNo,String name,List<EffectiveDay> days,MonthTotals totals){}
 public record MonthPage(YearMonth month,List<EmployeeMonth> employees,long total,int limit,int offset,boolean canManage){}
 public record ExceptionWrite(UUID employeeId,UUID companyId,LocalDate workDate,String kind,UUID typeId,Instant startAt,Instant endAt,String reason,String medicalReference){public ExceptionWrite(UUID employeeId,UUID companyId,LocalDate workDate,String kind,UUID typeId,Instant startAt,Instant endAt,String reason){this(employeeId,companyId,workDate,kind,typeId,startAt,endAt,reason,null);}}
 public record DecisionWrite(Long expectedVersion,String status,String note){}
 public record IntervalException(UUID id,UUID employeeId,UUID companyId,UUID storeId,LocalDate workDate,String kind,UUID typeId,String typeName,boolean paid,Instant startAt,Instant endAt,String reason,String status,UUID applicantId,UUID reviewerId,String reviewNote,String lastAction,long version,Instant createdAt,String medicalReference){public IntervalException(UUID id,UUID employeeId,UUID companyId,UUID storeId,LocalDate workDate,String kind,UUID typeId,String typeName,boolean paid,Instant startAt,Instant endAt,String reason,String status,UUID applicantId,UUID reviewerId,String reviewNote,String lastAction,long version,Instant createdAt){this(id,employeeId,companyId,storeId,workDate,kind,typeId,typeName,paid,startAt,endAt,reason,status,applicantId,reviewerId,reviewNote,lastAction,version,createdAt,null);}}
}
